return events
        .concatMap(event -> {
            if (policy.permits(event)) {
                return Mono.just(event);
            }
            metrics.broadcastDropped("untrusted-publisher");
            return Mono.defer(() -> auditTrail
                    .record(new AuditEntry("telemetry-broadcast", "authorization-denied", "denied", Instant.now(), event.deviceId())))
                    .then(Mono.<TelemetryEvent>empty());
        })
        .windowTimeout(windowMaxEvents, windowDuration)
        .concatMap(window -> window.collectList(), 1)
        .filter(batch -> !batch.isEmpty())
        .map(batch -> {
            Instant end = Instant.now();
            meterWindow();
            return new TelemetryWindowBroadcast(end.minus(windowDuration), end, List.copyOf(batch));
        });
